def search(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def searchInsert(nums, target):
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

def firstBadVersion(n, bad):
    def isBadVersion(v):
        return v >= bad

    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if isBadVersion(mid):
            right = mid
        else:
            left = mid + 1
    return left

def mySqrt(x):
    if x < 2:
        return x
    left, right = 1, x // 2
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == x:
            return mid
        elif mid * mid < x:
            left = mid + 1
        else:
            right = mid - 1
    return right

def guessNumber(n, pick):
    def guess(num):
        if num > pick: return -1
        elif num < pick: return 1
        else: return 0

    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        result = guess(mid)
        if result == 0:
            return mid
        elif result == 1:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def isPerfectSquare(num):
    if num < 2:
        return True
    left, right = 2, num // 2
    while left <= right:
        mid = (left + right) // 2
        sq = mid * mid
        if sq == num:
            return True
        elif sq < num:
            left = mid + 1
        else:
            right = mid - 1
    return False

def countNegatives(grid):
    count = 0
    n = len(grid[0])
    for row in grid:
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if row[mid] < 0:
                right = mid
            else:
                left = mid + 1
        count += n - left
    return count

def nextGreatestLetter(letters, target):
    left, right = 0, len(letters)
    while left < right:
        mid = (left + right) // 2
        if letters[mid] <= target:
            left = mid + 1
        else:
            right = mid
    return letters[left % len(letters)]

def findKthPositive(arr, k):
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        # number of missing positives before arr[mid]
        if arr[mid] - (mid + 1) >= k:
            right = mid
        else:
            left = mid + 1
    # left is the first index where missing >= k
    # answer = left + k (k missing numbers after left numbers present)
    return left + k

def arrangeCoins(n):
    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        coins_used = mid * (mid + 1) // 2
        if coins_used == n:
            return mid
        elif coins_used < n:
            left = mid + 1
        else:
            right = mid - 1
    return right

def searchMatrix(matrix, target):
    m, n = len(matrix), len(matrix[0])
    left, right = 0, m * n - 1
    while left <= right:
        mid = (left + right) // 2
        val = matrix[mid // n][mid % n]
        if val == target:
            return True
        elif val < target:
            left = mid + 1
        else:
            right = mid - 1
    return False

def singleNonDuplicate(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        # mid^1: if mid is even -> mid+1, if mid is odd -> mid-1
        if nums[mid] == nums[mid ^ 1]:
            left = mid + 1
        else:
            right = mid
    return nums[left]

def peakIndexInMountainArray(arr):
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < arr[mid + 1]:
            left = mid + 1
        else:
            right = mid
    return left

def checkIfExist(arr):
    arr.sort()
    n = len(arr)
    for i, val in enumerate(arr):
        target = val * 2
        left, right = 0, n - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target and mid != i:
                return True
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
    return False

def targetIndices(nums, target):
    nums.sort()
    left, right = 0, len(nums)
    # find first index >= target
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    start = lo
    # find first index > target
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    end = lo
    return list(range(start, end))

def minimumAbsDifference(arr):
    arr.sort()
    min_diff = float('inf')
    for i in range(len(arr) - 1):
        min_diff = min(min_diff, arr[i+1] - arr[i])
    result = []
    for i in range(len(arr) - 1):
        if arr[i+1] - arr[i] == min_diff:
            result.append([arr[i], arr[i+1]])
    return result

def intersection(nums1, nums2):
    nums2.sort()
    result = set()
    for num in nums1:
        left, right = 0, len(nums2) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums2[mid] == num:
                result.add(num)
                break
            elif nums2[mid] < num:
                left = mid + 1
            else:
                right = mid - 1
    return sorted(result)

def findMin(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    return nums[left]

def searchRotated(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        # left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # right half is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

def findPeakElement(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid
    return left

def verify_peak(nums, idx):
    n = len(nums)
    left_ok = (idx == 0 or nums[idx] > nums[idx-1])
    right_ok = (idx == n-1 or nums[idx] > nums[idx+1])
    return left_ok and right_ok

import math

def minEatingSpeed(piles, h):
    def canFinish(speed):
        return sum(math.ceil(p / speed) for p in piles) <= h

    left, right = 1, max(piles)
    while left < right:
        mid = (left + right) // 2
        if canFinish(mid):
            right = mid
        else:
            left = mid + 1
    return left

def shipWithinDays(weights, days):
    def canShip(capacity):
        day_count, curr_load = 1, 0
        for w in weights:
            if curr_load + w > capacity:
                day_count += 1
                curr_load = 0
            curr_load += w
        return day_count <= days

    left, right = max(weights), sum(weights)
    while left < right:
        mid = (left + right) // 2
        if canShip(mid):
            right = mid
        else:
            left = mid + 1
    return left

import bisect

def findRightInterval(intervals):
    # sorted list of (start, original_index)
    starts = sorted((iv[0], i) for i, iv in enumerate(intervals))
    start_vals = [s[0] for s in starts]

    result = []
    for start, end in intervals:
        pos = bisect.bisect_left(start_vals, end)
        if pos < len(starts):
            result.append(starts[pos][1])
        else:
            result.append(-1)
    return result

from collections import defaultdict

class TimeMap:
    def __init__(self):
        self.store = defaultdict(list)  # key -> [(timestamp, value)]

    def set(self, key, value, timestamp):
        self.store[key].append((timestamp, value))

    def get(self, key, timestamp):
        entries = self.store[key]
        if not entries:
            return ""
        left, right = 0, len(entries) - 1
        result = ""
        while left <= right:
            mid = (left + right) // 2
            if entries[mid][0] <= timestamp:
                result = entries[mid][1]
                left = mid + 1
            else:
                right = mid - 1
        return result

