def hIndex(citations):
    n = len(citations)
    left, right = 0, n
    while left < right:
        mid = (left + right) // 2
        if citations[mid] >= n - mid:
            right = mid
        else:
            left = mid + 1
    return n - left

def findClosestElements(arr, k, x):
    left, right = 0, len(arr) - k
    while left < right:
        mid = (left + right) // 2
        if x - arr[mid] > arr[mid + k] - x:
            left = mid + 1
        else:
            right = mid
    return arr[left:left + k]

def minDays(bloomDay, m, k):
    if m * k > len(bloomDay):
        return -1

    def canMake(day):
        bouquets = consecutive = 0
        for d in bloomDay:
            if d <= day:
                consecutive += 1
                if consecutive == k:
                    bouquets += 1
                    consecutive = 0
            else:
                consecutive = 0
        return bouquets >= m

    left, right = min(bloomDay), max(bloomDay)
    while left < right:
        mid = (left + right) // 2
        if canMake(mid):
            right = mid
        else:
            left = mid + 1
    return left

import math

def smallestDivisor(nums, threshold):
    def getSum(div):
        return sum(math.ceil(n / div) for n in nums)

    left, right = 1, max(nums)
    while left < right:
        mid = (left + right) // 2
        if getSum(mid) <= threshold:
            right = mid
        else:
            left = mid + 1
    return left

def maxDistance(position, m):
    position.sort()

    def canPlace(min_dist):
        placed = 1
        last = position[0]
        for pos in position[1:]:
            if pos - last >= min_dist:
                placed += 1
                last = pos
                if placed == m:
                    return True
        return False

    left, right = 1, (position[-1] - position[0]) // (m - 1)
    while left < right:
        mid = (left + right + 1) // 2  # upper mid to avoid infinite loop
        if canPlace(mid):
            left = mid
        else:
            right = mid - 1
    return left

import math

def minimizeArrayValue(nums):
    def feasible(max_val):
        # check if we can make all elements <= max_val
        # by only spreading excess to the left
        prefix_sum = 0
        for i, num in enumerate(nums):
            prefix_sum += num
            if math.ceil(prefix_sum / (i + 1)) > max_val:
                return False
        return True

    left, right = nums[0], max(nums)
    while left < right:
        mid = (left + right) // 2
        if feasible(mid):
            right = mid
        else:
            left = mid + 1
    return left

def findMedianSortedArrays(nums1, nums2):
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
    m, n = len(nums1), len(nums2)
    left, right = 0, m

    while left <= right:
        i = (left + right) // 2
        j = (m + n + 1) // 2 - i

        max_left1 = nums1[i-1] if i > 0 else float('-inf')
        min_right1 = nums1[i] if i < m else float('inf')
        max_left2 = nums2[j-1] if j > 0 else float('-inf')
        min_right2 = nums2[j] if j < n else float('inf')

        if max_left1 <= min_right2 and max_left2 <= min_right1:
            if (m + n) % 2 == 1:
                return float(max(max_left1, max_left2))
            else:
                return (max(max_left1, max_left2) + min(min_right1, min_right2)) / 2
        elif max_left1 > min_right2:
            right = i - 1
        else:
            left = i + 1

def splitArray(nums, k):
    def canSplit(max_sum):
        parts, curr = 1, 0
        for num in nums:
            if curr + num > max_sum:
                parts += 1
                curr = 0
            curr += num
        return parts <= k

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if canSplit(mid):
            right = mid
        else:
            left = mid + 1
    return left

def findInMountainArray(target, arr):
    n = len(arr)
    # Step 1: find peak
    left, right = 0, n - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < arr[mid + 1]:
            left = mid + 1
        else:
            right = mid
    peak = left

    # Step 2: search ascending part [0, peak]
    left, right = 0, peak
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # Step 3: search descending part [peak+1, n-1]
    left, right = peak + 1, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] > target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def kthSmallest(matrix, k):
    n = len(matrix)

    def countLessEqual(val):
        count = 0
        row, col = n - 1, 0
        while row >= 0 and col < n:
            if matrix[row][col] <= val:
                count += row + 1
                col += 1
            else:
                row -= 1
        return count

    left, right = matrix[0][0], matrix[n-1][n-1]
    while left < right:
        mid = (left + right) // 2
        if countLessEqual(mid) >= k:
            right = mid
        else:
            left = mid + 1
    return left

def smallestDistancePair(nums, k):
    nums.sort()
    n = len(nums)

    def countPairs(max_dist):
        count = left = 0
        for right in range(n):
            while nums[right] - nums[left] > max_dist:
                left += 1
            count += right - left
        return count

    left, right = 0, nums[-1] - nums[0]
    while left < right:
        mid = (left + right) // 2
        if countPairs(mid) >= k:
            right = mid
        else:
            left = mid + 1
    return left

import bisect

def maxEnvelopes(envelopes):
    # sort by width asc, then height desc
    envelopes.sort(key=lambda x: (x[0], -x[1]))

    # LIS on heights using binary search
    tails = []
    for _, h in envelopes:
        pos = bisect.bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
    return len(tails)

def aggressiveCows(stalls, c):
    stalls.sort()

    def canPlace(min_dist):
        cows_placed = 1
        last_pos = stalls[0]
        for i in range(1, len(stalls)):
            if stalls[i] - last_pos >= min_dist:
                cows_placed += 1
                last_pos = stalls[i]
                if cows_placed == c:
                    return True
        return cows_placed >= c

    left, right = 1, stalls[-1] - stalls[0]
    while left < right:
        mid = (left + right + 1) // 2  # upper mid for "find maximum"
        if canPlace(mid):
            left = mid
        else:
            right = mid - 1
    return left

def allocateMinPages(books, m):
    if m > len(books):
        return -1

    def studentsNeeded(max_pages):
        students = 1
        curr = 0
        for pages in books:
            if curr + pages > max_pages:
                students += 1
                curr = 0
            curr += pages
        return students

    left, right = max(books), sum(books)
    while left < right:
        mid = (left + right) // 2
        if studentsNeeded(mid) <= m:
            right = mid
        else:
            left = mid + 1
    return left

def searchWithDuplicates(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return True
        # can't determine sorted half — shrink both ends
        if nums[left] == nums[mid] == nums[right]:
            left += 1
            right -= 1
        elif nums[left] <= nums[mid]:  # left half sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # right half sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return False

def minDaysToDisconnect(grid):
    from collections import deque
    import copy

    def count_islands(g):
        rows, cols = len(g), len(g[0])
        visited = [[False]*cols for _ in range(rows)]
        count = 0
        for r in range(rows):
            for c in range(cols):
                if g[r][c] == 1 and not visited[r][c]:
                    count += 1
                    queue = deque([(r, c)])
                    visited[r][c] = True
                    while queue:
                        x, y = queue.popleft()
                        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nx, ny = x+dx, y+dy
                            if 0<=nx<rows and 0<=ny<cols and g[nx][ny]==1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))
        return count

    if count_islands(grid) != 1:
        return 0

    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                grid[r][c] = 0
                if count_islands(grid) != 1:
                    return 1
                grid[r][c] = 1
    return 2

def countElements(nums):
    lo, hi = min(nums), max(nums)
    return sum(1 for x in nums if lo < x < hi)

def fixedPoint(nums):
    lo, hi = 0, len(nums) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == mid:
            ans = mid
            hi = mid - 1
        elif nums[mid] < mid:
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def floorCeiling(nums, target):
    def floor_bs(arr, t):
        lo, hi, ans = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] <= t:
                ans = arr[mid]
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

    def ceil_bs(arr, t):
        lo, hi, ans = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] >= t:
                ans = arr[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

    return floor_bs(nums, target), ceil_bs(nums, target)

def countOccurrences(nums, target):
    def first(arr, t):
        lo, hi, ans = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == t:
                ans = mid
                hi = mid - 1
            elif arr[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

    def last(arr, t):
        lo, hi, ans = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == t:
                ans = mid
                lo = mid + 1
            elif arr[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

    f = first(nums, target)
    if f == -1:
        return 0
    return last(nums, target) - f + 1

def searchRange(nums, target):
    def find_first(arr, t):
        lo, hi, ans = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == t:
                ans = mid; hi = mid - 1
            elif arr[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

    def find_last(arr, t):
        lo, hi, ans = 0, len(arr)-1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == t:
                ans = mid; lo = mid + 1
            elif arr[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

    return [find_first(nums, target), find_last(nums, target)]

def leftMostOccurrence(nums, target):
