def isPerfectSquareBS(n):
    if n < 1:
        return False
    lo, hi = 1, n
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

from math import gcd

def findGCDArray(nums):
    return gcd(min(nums), max(nums))

def daysBetweenDates(date1, date2):
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_from_epoch(year, month, day):
        months = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = (year - 1) * 365 + (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
        if is_leap(year):
            months[2] = 29
        total += sum(months[:month]) + day
        return total

    y1, m1, d1 = date1
    y2, m2, d2 = date2
    return abs(days_from_epoch(y1, m1, d1) - days_from_epoch(y2, m2, d2))

def lowerBound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def upperBound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def findMinRotated(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]

def searchNearlySorted(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if mid - 1 >= lo and nums[mid - 1] == target:
            return mid - 1
        if mid + 1 <= hi and nums[mid + 1] == target:
            return mid + 1
        if mid - 1 >= lo and nums[mid - 1] < target:
