def maxValue(n, index, maxSum):
    def min_sum(val, count):
        # minimum sum of 'count' elements ending/starting at 'val', decreasing by 1
        if val >= count:
            # forms: val, val-1, ..., val-count+1
            return (val + val - count + 1) * count // 2
        else:
            # goes down to 1, then pads with 1s
            return (val * (val + 1)) // 2 + (count - val)

    def feasible(v):
        left_count = index
        right_count = n - index - 1
        total = v + min_sum(v - 1, left_count) + min_sum(v - 1, right_count)
        return total <= maxSum

    lo, hi = 1, maxSum
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

