def findMedianSortedArraysKth(nums1, nums2):
    def find_kth(a, i, b, j, k):
        if i >= len(a): return b[j + k - 1]
        if j >= len(b): return a[i + k - 1]
        if k == 1: return min(a[i], b[j])
        half = k // 2
        a_val = a[i + half - 1] if i + half - 1 < len(a) else float('inf')
        b_val = b[j + half - 1] if j + half - 1 < len(b) else float('inf')
        if a_val <= b_val:
            return find_kth(a, i + half, b, j, k - half)
        else:
            return find_kth(a, i, b, j + half, k - half)

    total = len(nums1) + len(nums2)
    if total % 2 == 1:
        return float(find_kth(nums1, 0, nums2, 0, total // 2 + 1))
    else:
        return (find_kth(nums1, 0, nums2, 0, total // 2) +
                find_kth(nums1, 0, nums2, 0, total // 2 + 1)) / 2.0

