class SegTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [float('inf')] * (2 * self.n)
        for i, v in enumerate(arr):
            self.tree[self.n + i] = v
        for i in range(self.n - 1, 0, -1):
            self.tree[i] = min(self.tree[2*i], self.tree[2*i+1])

    def query_min(self, l, r):  # inclusive [l, r]
        res = float('inf')
        l += self.n
        r += self.n + 1
        while l < r:
            if l & 1:
                res = min(res, self.tree[l])
                l += 1
            if r & 1:
                r -= 1
                res = min(res, self.tree[r])
            l >>= 1
            r >>= 1
        return res

    def find_leftmost_min(self, l, r):
        # binary search: find leftmost index of min in [l,r]
        min_val = self.query_min(l, r)
        lo, hi = l, r
        while lo < hi:
            mid = (lo + hi) // 2
            if self.query_min(lo, mid) == min_val:
                hi = mid
            else:
                lo = mid + 1
        return lo

