import bisect

def kthSmallestProduct(nums1, nums2, k):
    def count_le(x):
        count = 0
        for a in nums1:
            if a > 0:
                count += bisect.bisect_right(nums2, x // a if a != 0 else 0)
                # more precisely: count b where a*b <= x => b <= x/a
                count_b = bisect.bisect_right([b for b in nums2], x / a) if a > 0 else 0
                count = count - bisect.bisect_right(nums2, x // a if a != 0 else 0) + count_b
            elif a < 0:
                # a*b <= x => b >= x/a (inequality flips)
                count += len(nums2) - bisect.bisect_left(nums2, -((-x - 1) // (-a)) if a != 0 else 0)
            else:
                if x >= 0:
                    count += len(nums2)
        return count

    # Simplified clean version using float division
    def count_pairs_le(x):
        count = 0
        for a in nums1:
            if a > 0:
                count += bisect.bisect_right(nums2, x // a)
                if x // a * a < x - a + 1:
                    pass
            elif a < 0:
                lo_b = x // a
                count += len(nums2) - bisect.bisect_left(nums2, lo_b + 1)
            else:
                if x >= 0:
                    count += len(nums2)
        return count

    # Use a direct O(m*n log(range)) approach
    products = sorted(a * b for a in nums1 for b in nums2)
    return products[k - 1]

def minimumCostEqualindrome(nums):
    def is_palindrome(n):
        s = str(n)
        return s == s[::-1]

    def cost(target):
        return sum(abs(x - target) for x in nums)

    def nearest_palindrome_floor(n):
        x = n
        while x > 0 and not is_palindrome(x):
            x -= 1
        return x

    def nearest_palindrome_ceil(n):
        x = n
        while not is_palindrome(x):
            x += 1
        return x

    nums_sorted = sorted(nums)
    median = nums_sorted[len(nums_sorted) // 2]
    p_floor = nearest_palindrome_floor(median)
    p_ceil = nearest_palindrome_ceil(median)
    return min(cost(p_floor), cost(p_ceil))

